"""Step 5b (PD-24): the OpenAPI component schemas, generated by ``gen-json-schema`` and trimmed, on the toy library."""

import json
from pathlib import Path

import pytest

from rdf_persistence.generation.steps import COMPONENTS_STEP
from rdf_persistence.services.artifacts import COMPONENTS_FILE
from rdf_persistence.services.schema import load_schema
from rdf_persistence.services.schema_structure import is_bookkeeping, is_internal

from .conftest import ROOT_SCHEMA, TOY
from .golden import TOY_TARGET, assert_matches_toy, run_toy

BOOKKEEPING = {"created", "modified", "creator", "contributor", "version"}


@pytest.fixture(scope="module")
def rendered(tmp_path_factory: pytest.TempPathFactory) -> Path:
    return run_toy(COMPONENTS_STEP, tmp_path_factory.mktemp("components"))


@pytest.fixture(scope="module")
def schemas(rendered: Path) -> dict:
    text = (rendered / str(TOY_TARGET.python) / COMPONENTS_FILE).read_text(encoding="utf-8")
    return json.loads(text)["schemas"]


def test_the_output_equals_the_committed_tree(rendered: Path) -> None:
    assert_matches_toy(rendered, f"generated/{COMPONENTS_FILE}")


def test_every_class_of_the_schema_has_a_component_schema(schemas: dict) -> None:
    view = load_schema(TOY / ROOT_SCHEMA)
    assert {"Book", "Chapter", "Note", "Scan", "Library", "Genre"} <= set(schemas)
    assert set(view.all_classes()) <= set(schemas), "a schema for every class"


def test_the_references_point_into_the_components_of_an_openapi_document(schemas: dict) -> None:
    text = json.dumps(schemas)
    assert "#/$defs/" not in text
    assert schemas["Book"]["properties"]["chapters"]["items"] == {
        "$ref": "#/components/schemas/Chapter"
    }


def test_no_bookkeeping_slot_is_in_any_schema(schemas: dict) -> None:
    leaked = {
        (name, prop)
        for name, schema in schemas.items()
        for prop in schema.get("properties", {})
        if prop in BOOKKEEPING
    }
    assert not leaked, "the session writes them; the API never shows them"


def test_the_bookkeeping_and_internal_slots_of_every_class_are_left_out(schemas: dict) -> None:
    view = load_schema(TOY / ROOT_SCHEMA)
    for cls in view.all_classes():
        hidden = {
            s.name for s in view.class_induced_slots(cls) if is_bookkeeping(s) or is_internal(s)
        }
        assert not hidden & set(schemas[cls].get("properties", {})), cls


def test_a_required_slot_that_is_left_out_is_no_longer_required(schemas: dict) -> None:
    assert not BOOKKEEPING & set(schemas["Book"].get("required", []))
    assert schemas["Book"]["required"] == ["id", "label"]


def test_the_identifier_is_read_only_because_the_service_assigns_it(schemas: dict) -> None:
    assert schemas["Book"]["properties"]["id"]["readOnly"] is True
    assert "readOnly" not in schemas["Book"]["properties"]["label"]


def test_the_output_is_reproducible(rendered: Path, tmp_path: Path) -> None:
    again = run_toy(COMPONENTS_STEP, tmp_path)
    name = Path(str(TOY_TARGET.python)) / COMPONENTS_FILE
    assert (again / name).read_bytes() == (rendered / name).read_bytes()


def test_a_target_that_serves_nothing_gets_no_components_file(tmp_path: Path) -> None:
    quiet = TOY_TARGET.model_copy(update={"openapi": False})
    staged = run_toy(COMPONENTS_STEP, tmp_path, quiet)
    assert not list(staged.rglob(COMPONENTS_FILE)), "the target switched the step off"
